def monotonic(l):
    # Helper to check duplicates recursively
    def has_duplicates(seq, seen=None):
        if seen is None:
            seen = set()
        if not seq:
            return False
        if seq[0] in seen:
            return True
        seen.add(seq[0])
        return has_duplicates(seq[1:], seen)

    # Helper to check strictly increasing recursively
    def strictly_increasing(seq):
        if len(seq) <= 1:
            return True
        return seq[0] < seq[1] and strictly_increasing(seq[1:])

    # Helper to check strictly decreasing recursively
    def strictly_decreasing(seq):
        if len(seq) <= 1:
            return True
        return seq[0] > seq[1] and strictly_decreasing(seq[1:])

    # Helper to sum recursively for list of numbers
    def sum_list(seq):
        if not seq:
            return 0
        return seq[0] + sum_list(seq[1:])

    # Helper to sum recursively for strings (concatenate)
    def sum_string(seq):
        if not seq:
            return ""
        return seq[0] + sum_string(seq[1:])

    # Check duplicates first
    if has_duplicates(l):
        return False

    # For list (numbers)
    if isinstance(l, list):
        if strictly_increasing(l) or strictly_decreasing(l):
            return True, sum_list(l)
        else:
            return False

    # For string
    if isinstance(l, str):
        if strictly_increasing(l) or strictly_decreasing(l):
            return True, sum_string(l)
        else:
            return False

    # If neither list nor string, just return False (not specified)
    return False


