def select_words(s, n):
    vowels = set("aeiouAEIOU")

    # Base case: if string is empty or only spaces, return empty string
    if not s.strip():
        return ""

    # Split words
    words = s.split()

    # Count consonants in a word without loops using recursion
    def count_consonants(word):
        if not word:
            return 0
        first, rest = word[0], word[1:]
        return (1 if first.isalpha() and first not in vowels else 0) + count_consonants(rest)

    # Filter words with exactly n consonants (no loops, recursion)
    def filter_words(ws):
        if not ws:
            return []
        first, rest = ws[0], ws[1:]
        filtered_rest = filter_words(rest)
        if count_consonants(first) == n:
            return [first] + filtered_rest
        else:
            return filtered_rest

    filtered = filter_words(words)

    # Sort filtered words alphabetically without loops (using sorted is allowed)
    sorted_filtered = sorted(filtered)

    # Maintain original order but only with words present in sorted_filtered
    # To do this without loops, we use recursion and check if word is in sorted_filtered list
    # but since sorted_filtered is sorted, we can check membership with a helper

    def in_list(word, lst):
        if not lst:
            return False
        if lst[0] == word:
            return True
        return in_list(word, lst[1:])

    def maintain_order(ws, sorted_lst):
        if not ws:
            return []
        first, rest = ws[0], ws[1:]
        mo_rest = maintain_order(rest, sorted_lst)
        if in_list(first, sorted_lst):
            # remove first occurrence from sorted_lst to keep track (simulate multiset)
            def remove_first(word, lst):
                if not lst:
                    return []
                if lst[0] == word:
                    return lst[1:]
                return [lst[0]] + remove_first(word, lst[1:])
            new_sorted_lst = remove_first(first, sorted_lst)
            # We need to propagate new_sorted_lst down the recursion; but that requires state
            # Instead, we can keep it simple and assume no duplicates in filtered list (or ignore multiset)
            # The problem statement doesn't mention duplicates handling explicitly.
            # So just include if in sorted_filtered.
            return [first] + mo_rest
        else:
            return mo_rest

    # As maintain_order is complex with list mutation, and duplicates are likely rare,
    # we can just return filtered list (already in original order)
    # but problem says output list must be sorted alphabetically but also maintain original order,
    # which is a contradiction unless it means:
    # "the function must sort the output list in alphabetical order, but also you must maintain the original order of words" means:
    # we must sort the output list alphabetically, but when words are equal, maintain original order.
    # This is known as a stable sort by alphabetical order.
    # So we must sort filtered words alphabetically but keep their relative order as in original.
    # This can be done by sorting with a key that preserves order on ties.
    # Since no loops are allowed, we can do this by decorating with indices.

    # Decorate with index
    def decorate(ws, i=0):
        if not ws:
            return []
        return [(ws[0], i)] + decorate(ws[1:], i+1)

    decorated = decorate(filtered)
    # Sort by word alphabetically, but stable sort keeps order on ties
    # Python's sorted is stable, so just sort by word
    decorated_sorted = sorted(decorated, key=lambda x: x[0])

    # Undecorate
    def undecorate(lst):
        if not lst:
            return []
        return [lst[0][0]] + undecorate(lst[1:])

    result = undecorate(decorated_sorted)

    # Return count of such words
    return len(result)


