def parse_nested_parens(text):
    """
    Given a string of groups of parentheses separated by whitespace,
    return a list of the deepest nesting level for each group.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    results = []
    groups = text.split()

    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
                if current_depth < 0:
                    raise ValueError(f"Unbalanced parentheses in group: {group}")
            else:
                raise ValueError(f"Invalid character '{char}' in group: {group}")
        if current_depth != 0:
            raise ValueError(f"Unbalanced parentheses in group: {group}")
        results.append(max_depth)

    return results


