def next_power_of_2(n: int) -> int:
    """
    Returns the smallest power of 2 greater than or equal to n.
    For n <= 0, returns 1.
    """
    if n <= 0:
        return 1
    # If n is already a power of two, return n
    if (n & (n - 1)) == 0:
        return n
    power = 1
    while power < n:
        power <<= 1
    return power

