def get_gcd(arr):
    from math import gcd
    if not arr:
        raise ValueError("Input array must not be empty")
    if 0 not in arr:
        raise ValueError("Input array must contain at least one zero")

    # Filter out zeros since gcd with zero is the other number
    non_zero_elements = [x for x in arr if x != 0]

    # If all elements are zero, gcd is undefined or can be considered 0,
    # but problem states gcd must be strictly positive, so raise error
    if not non_zero_elements:
        raise ValueError("Array contains only zeros, gcd must be strictly positive")

    current_gcd = non_zero_elements[0]
    for num in non_zero_elements[1:]:
        current_gcd = gcd(current_gcd, num)

    # gcd is always non-negative, ensure strictly positive
    if current_gcd <= 0:
        raise ValueError("GCD must be strictly positive")
    return current_gcd


