def dict_depth(obj):
    """
    Calculate the depth of a dictionary, counting nested dictionaries,
    lists, and tuples towards the depth.

    Depth is defined as:
    - 0 if obj is not a dict, list, or tuple
    - 1 + max depth of any nested dict, list, or tuple inside obj

    Args:
        obj: The object to measure depth of.

    Returns:
        int: The depth as defined above.
    """
    if isinstance(obj, dict):
        if not obj:
            return 1
        return 1 + max(dict_depth(v) for v in obj.values())
    elif isinstance(obj, (list, tuple)):
        if not obj:
            return 1
        return 1 + max(dict_depth(i) for i in obj)
    else:
        return 0


