def find_solution(a, b, n):
    """
    Finds one integer solution (x, y) to the equation a*x + b*y = n, if it exists.

    Returns:
        (x, y) tuple if a solution exists,
        None if no integer solution exists.
    """
    def extended_gcd(aa, bb):
        """
        Extended Euclidean Algorithm
        Returns a tuple (g, x, y) such that a*x + b*y = g = gcd(a, b)
        """
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(abs(a), abs(b))

    # No solution if gcd does not divide n
    if n % g != 0:
        return None

    # Scale the solution to n
    x0 *= n // g
    y0 *= n // g

    # Adjust signs depending on original a and b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)


