    solution = find_solution(a, b, n)
    if solution:
        x, y = solution
        print(f"Solution for {a}*x + {b}*y = {n} is x = {x}, y = {y}")
        # Verify the solution
        print(f"Verification: {a}*{x} + {b}*{y} = {a*x + b*y}")
    else:
        print("No integer solution exists.")

