def dict_depth(d):
    """
    Calculate the maximum depth of nested dictionaries within the given dictionary.

    Args:
        d (dict): The dictionary to evaluate.

    Returns:
        int: The maximum depth of nested dictionaries.
    """
    if not isinstance(d, dict) or not d:
        return 0
    return 1 + max(dict_depth(v) for v in d.values() if isinstance(v, dict))


