def remove_column(data, col):
    """
    Recursively remove all occurrences of a specified key (col) from nested dictionaries and lists.

    Args:
        data (dict, list, or other): The nested data structure.
        col (str): The key to remove from dictionaries.

    Returns:
        The data structure with the specified key removed.
    """
    if isinstance(data, dict):
        # Create a new dict without the specified key, and recursively apply to values
        return {k: remove_column(v, col) for k, v in data.items() if k != col}
    elif isinstance(data, list):
        # Recursively apply to each element in the list
        return [remove_column(item, col) for item in data]
    else:
        # For other data types, return as is
        return data

