def check_subset(set1, set2):
    """
    Check if set1 is a subset of set2.

    Args:
        set1 (iterable): The first set or iterable.
        set2 (iterable): The second set or iterable.

    Returns:
        bool: True if set1 is a subset of set2, False otherwise.
    """
    return set(set1).issubset(set(set2))


