def lcm(a, b):
    """Return the least common multiple of two integers a and b."""
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    if a == 0 or b == 0:
        return 0  # LCM of zero with any number is zero

    return abs(a * b) // gcd(a, b)

