def next_smallest_palindrome(num: int) -> int:
    """
    Find the smallest palindrome strictly greater than the given number.

    Args:
        num (int): The input number.

    Returns:
        int: The next smallest palindrome greater than num.
    """
    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    def create_palindrome(left: str, middle: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + middle + left[::-1])
        else:
            return int(left + left[::-1])

    s = str(num)
    length = len(s)

    # If all 9's, next palindrome is 10...01
    if is_all_nines(s):
        return num + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    odd_length = (length % 2 != 0)
    mid = length // 2

    if odd_length:
        left = s[:mid]
        middle = s[mid]
        right = s[mid+1:]
    else:
        left = s[:mid]
        middle = ''
        right = s[mid:]

    # Create palindrome by mirroring left + middle
    if odd_length:
        palindrome = create_palindrome(left, middle, True)
    else:
        palindrome = create_palindrome(left, middle, False)

    if palindrome > num:
        return palindrome

    # If palindrome is not greater, need to increment the middle part
    if odd_length:
        # Increment middle digit and propagate if needed
        middle_int = int(middle)
        middle_int += 1
        if middle_int <= 9:
            palindrome = create_palindrome(left, str(middle_int), True)
            if palindrome > num:
                return palindrome
        # If middle digit was 9 and after increment needs carry
        # Set middle to 0 and increment left part as a number
        middle = '0'
        left_int = int(left) if left else 0
        left_int += 1
        left = str(left_int).zfill(len(left))
        palindrome = create_palindrome(left, middle, True)
        return palindrome
    else:
        # Even length: increment left and mirror
        left_int = int(left)
        left_int += 1
        left = str(left_int).zfill(len(left))
        palindrome = create_palindrome(left, middle, False)
        return palindrome


