def drop_empty(d):
    """
    Recursively remove keys with empty values from a dictionary.
    Empty values are considered to be:
    - None
    - Empty string ''
    - Empty list []
    - Empty dict {}
    - Empty tuple ()
    - Empty set set()

    Args:
        d (dict): The input dictionary.

    Returns:
        dict: A new dictionary with all empty values removed.
    """
    if not isinstance(d, dict):
        return d

    def is_empty(value):
        if value is None:
            return True
        if isinstance(value, (str, list, dict, tuple, set)) and len(value) == 0:
            return True
        return False

    result = {}
    for k, v in d.items():
        if isinstance(v, dict):
            cleaned = drop_empty(v)
            if not is_empty(cleaned):
                result[k] = cleaned
        elif not is_empty(v):
            result[k] = v

    return result


