def filter_data(data, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters students based on height and width criteria.

    Parameters:
        data (dict): Dictionary where keys are student names and values are dicts with 'height' and 'width'.
                     Example: {'Alice': {'height': 160, 'width': 50}, ...}
        min_height (int or float, optional): Minimum height to include.
        max_height (int or float, optional): Maximum height to include.
        min_width (int or float, optional): Minimum width to include.
        max_width (int or float, optional): Maximum width to include.

    Returns:
        dict: Filtered dictionary of students matching the criteria.
    """
    filtered = {}
    for student, measurements in data.items():
        height = measurements.get('height')
        width = measurements.get('width')

        if height is None or width is None:
            # Skip if any measurement missing
            continue

        if min_height is not None and height < min_height:
            continue
        if max_height is not None and height > max_height:
            continue
        if min_width is not None and width < min_width:
            continue
        if max_width is not None and width > max_width:
            continue

        filtered[student] = measurements

    return filtered


