def find_solution(a, b, n):
    """
    Find one integer solution (x, y) to the equation:
        a*x + b*y = n

    Returns:
        (x, y) if a solution exists, else None.

    Uses the Extended Euclidean Algorithm to find one particular solution.
    """

    def extended_gcd(aa, bb):
        """Return (g, x, y) such that a*x + b*y = g = gcd(a, b)"""
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)

    # No solution if n is not divisible by gcd(a, b)
    if n % g != 0:
        return None

    # Scale the solution to n
    x = x0 * (n // g)
    y = y0 * (n // g)

    return (x, y)


