def odd_length_sum(arr):
    total = 0
    n = len(arr)
    # Iterate over all odd lengths
    for length in range(1, n + 1, 2):
        # For each subarray of this odd length
        for start in range(n - length + 1):
            total += sum(arr[start:start + length])
    return total

