def drop_empty(d):
    """
    Return a new dictionary with all items removed where the value is considered empty.
    Empty values are those that are:
      - None
      - Empty strings
      - Empty containers (lists, tuples, sets, dicts)
    This function processes nested dictionaries recursively.

    Args:
        d (dict): The input dictionary.

    Returns:
        dict: A new dictionary with empty items removed.
    """
    if not isinstance(d, dict):
        raise ValueError("Input must be a dictionary")

    def is_empty(value):
        if value is None:
            return True
        if isinstance(value, (str, bytes)) and len(value) == 0:
            return True
        if isinstance(value, (list, tuple, set, dict)) and len(value) == 0:
            return True
        return False

    def clean_dict(dct):
        new_dict = {}
        for k, v in dct.items():
            if isinstance(v, dict):
                cleaned = clean_dict(v)
                if not is_empty(cleaned):
                    new_dict[k] = cleaned
            else:
                if not is_empty(v):
                    new_dict[k] = v
        return new_dict

    return clean_dict(d)


