def substract_elements(t):
    """
    Recursively subtract all elements in the nested tuple structure.

    Example:
    substract_elements((10, (3, 2), 1)) 
    -> 10 - 3 - 2 - 1 = 4
    """
    def flatten_and_subtract(items):
        result = None
        for item in items:
            if isinstance(item, tuple):
                val = flatten_and_subtract(item)
            else:
                val = item
            if result is None:
                result = val
            else:
                result -= val
        return result

    return flatten_and_subtract(t)


