    print(substract_elements(nested_tuple))  # Output: 4

def tuple_to_set(tuples):
    """
    Converts a tuple or a tuple of tuples into a set.

    If the input is a single tuple, returns a set of its elements.
    If the input is a tuple of tuples, returns a set of tuples.

    Args:
        tuples (tuple or tuple of tuples): The input tuple(s).

    Returns:
        set: A set containing the unique elements or tuples.
    """
    # Check if the input is a tuple of tuples
    if all(isinstance(item, tuple) for item in tuples):
        return set(tuples)
    else:
        return set(tuples)


