if __name__ == "__main__":
    # Single tuple to set
    t1 = (1, 2, 3, 4, 5)
    print(tuple_to_set(t1))  # Output: {1, 2, 3, 4, 5}

    # Tuple of tuples to set of tuples
    t2 = ((1, 2), (3, 4), (5, 6))
    print(tuple_to_set(t2))  # Output: {(1, 2), (3, 4), (5, 6)}

    # Tuple with repeated elements
    t3 = (1, 2, 2, 3, 3, 3)
    print(tuple_to_set(t3))  # Output: {1, 2, 3}
